import 'dart:convert';import 'dart:io';import 'package:flutter_test/flutter_test.dart';import '../lib/core/services/budur_source.dart';import '../lib/core/services/budur_verse_linker.dart';import '../lib/core/models/ayah.dart';import '../lib/core/models/surah.dart';
void main(){test('inventory only, not source coverage certification',(){final src=File('/tmp/offline-corpus-preparation/budur-reference-text-1224.txt').readAsStringSync();final chapters=(jsonDecode(File('assets/data/surahs.json').readAsStringSync()) as List).map((r)=>Surah.fromJson(Map<String,dynamic>.from(r)));final out=<Map<String,dynamic>>[];
for(final s in chapters){final verses=(jsonDecode(File('assets/data/surahs/${s.id}.json').readAsStringSync())as List).map((r)=>Ayah.fromRow(Map<String,dynamic>.from(r))).toList();final passages=BudurSource.passages(src,s,verses);for(var n=0;n<passages.length;n++){final p=passages[n];final q=BudurVerseLinker.quotes(p.text);out.add({'surah':s.id,'n':n,'page':p.firstPage,'lastPage':p.lastPage,'text':p.text,'assigned':p.ayahs,'quotes':q,'candidates':q.map((q)=>BudurVerseLinker.occurrences(q,verses).map((c)=>c.ayah).toList()).toList()});}}
File('/tmp/offline-corpus-preparation/budur-current-1224-inventory.json').writeAsStringSync(jsonEncode(out));print('${out.length} source passages inventoried');});}
